-- Name: item; Type: TABLE; Schema: memory; Owner: -

CREATE TABLE memory.item (
    id bigint NOT NULL,
    reader text NOT NULL,
    kind text NOT NULL,
    source text NOT NULL,
    source_ref text,
    conversation text,
    at timestamp with time zone DEFAULT now() NOT NULL,
    subject text,
    text text NOT NULL,
    records text[] DEFAULT '{}'::text[] NOT NULL,
    citations jsonb DEFAULT '[]'::jsonb NOT NULL,
    people text[] DEFAULT '{}'::text[] NOT NULL,
    log_ids bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    importance real DEFAULT 0.5 NOT NULL,
    confidence real DEFAULT 0.7 NOT NULL,
    superseded_by bigint,
    deleted_at timestamp with time zone,
    tsv tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('english'::regconfig, COALESCE(subject, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, text), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, text), 'C'::"char"))) STORED,
    embedding public.vector,
    embed_model text,
    CONSTRAINT item_confidence_check CHECK (((confidence > (0)::double precision) AND (confidence <= (1)::double precision))),
    CONSTRAINT item_importance_check CHECK (((importance > (0)::double precision) AND (importance <= (1)::double precision))),
    CONSTRAINT item_kind_check CHECK ((kind = ANY (ARRAY['fact'::text, 'preference'::text, 'instruction'::text, 'commitment'::text, 'summary'::text]))),
    CONSTRAINT item_reader_check CHECK ((reader <> ''::text)),
    CONSTRAINT item_source_check CHECK ((source ~ '^[a-z_]{1,40}$'::text)),
    CONSTRAINT item_text_check CHECK (((text <> ''::text) AND (length(text) <= 8000)))
);


