    binding_kind,
    link_contract,
    reason,
    why_not,
    evidence_handles,
    reviewed_by,
    reviewed_at,
    review_action_id,
    markings,
    recorded_at,
    superseded_at
   FROM ontology.links_seen() links_seen(link_id, link_type, from_object, to_object, tier, binding_kind, link_contract, reason, why_not, evidence_handles, reviewed_by, reviewed_at, review_action_id, markings, recorded_at, superseded_at);


