    CONSTRAINT template_source_ref_check CHECK (((source_ref IS NULL) OR (length(source_ref) <= 400))),
    CONSTRAINT template_style_notes_check CHECK ((length(style_notes) <= 2000)),
    CONSTRAINT template_uses_check CHECK ((uses >= 0))
);


